(async()=>{if(new URLSearchParams(location.search).get('profile')!=='hearts-islands-check')return;const wait=ms=>new Promise(r=>setTimeout(r,ms));while(!window.EmberQA)await wait(100);const q=EmberQA,W=EmberTerrain,D=SurvivalData,T=THREE;document.getElementById('welcome').hidden=true;const panel=document.createElement('section');panel.style='position:fixed;inset:0;background:white;overflow:auto;z-index:10000;color:#234;padding:16px';const report=document.createElement('pre');report.id='report';panel.append(report);document.body.append(panel);const result={},check=(k,v)=>{result[k]=!!v;report.textContent=JSON.stringify(result,null,2);if(!v)throw Error(k);};q.apply({...D.fresh(),hp:97.5,worldTime:360,automaticTime:false,weatherMode:'clear'});q.setPlaying(true);q.hud();check('twentyHearts',document.querySelectorAll('#hearts svg').length===20);check('oneHalfHeart',document.querySelectorAll('#hearts [data-fill="50"]').length===1);const heart=document.getElementById('hearts').cloneNode(true);heart.id='heart-preview';heart.style='width:230px;padding:12px;background:#fffff2;display:grid;grid-template-columns:repeat(10,1fr)';panel.append(heart);const capture=id=>{q.renderer.render(q.scene,q.camera);const img=document.createElement('img');img.id=id;img.style='width:48%';img.src=q.renderer.domElement.toDataURL();panel.append(img);};
for(const [n,i]of W.islands.filter(i=>i.giant).entries()){q.apply({...D.fresh(),x:i.x,z:i.z,y:i.y,worldTime:360,automaticTime:false,weatherMode:'clear'});q.setPlaying(true);q.sky.update(q.state,0,true);q.camera.position.set(i.x+i.r*1.35,i.y+i.r*.58,i.z+i.r*1.55);q.camera.lookAt(i.x,i.y-i.depth*.25,i.z);await wait(500);capture('giant-'+n);const surface=q.world.islandGroups.find(v=>v.i===i).g.children.find(o=>o.userData.giantIslandTop);surface.updateWorldMatrix(true,false);const ray=new T.Raycaster(new T.Vector3(i.x,i.y+10,i.z),new T.Vector3(0,-1,0));check('solidTop'+n,Math.abs(ray.intersectObject(surface)[0]?.point.y-i.y)<.01);check('solidUnderside'+n,q.world.blocked(i.x,i.z,i.y-10,q.state));}
for(let n=0;n<10;n++){const c=W.caves[n],p=W.cavePoint(c,0,12);q.apply({...D.fresh(),...p,y:W.caveFloor(c,0,12),yaw:Math.atan2(-c.fx,-c.fz),pitch:.1,worldTime:360,automaticTime:false,weatherMode:'clear'});q.setPlaying(true);await wait(120);capture('cave-'+n);}result.done=true;report.textContent=JSON.stringify(result,null,2);const show=document.createElement('button');show.textContent='ハート表示をゲーム画面で確認';show.onclick=()=>{panel.hidden=true;const i=W.islands.find(i=>i.giant);q.apply({...D.fresh(),x:i.x,z:i.z,y:i.y,hp:97.5,worldTime:360,automaticTime:false,weatherMode:'clear'});q.setPlaying(true);q.close(false);};panel.prepend(show);document.title='ハート・巨大浮島・岩肌の検証完了';})().catch(e=>{document.title='QA error';document.getElementById('report').textContent+='\n'+e.stack;});
